{
  "units": [
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "Except as provided in paragraph (d) of 14 CFR 91.213, no person may take off an aircraft with inoperative instruments or equipment installed unless specified conditions (1) through (5) of paragraph (a) are met."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F013"],
      "kind": "condition",
      "meaning": "For takeoff of an aircraft with inoperative instruments or equipment installed under paragraph (a), an approved Minimum Equipment List must exist for that aircraft."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F013"],
      "kind": "condition",
      "meaning": "For takeoff under paragraph (a), the aircraft must have within it a letter of authorization issued by the responsible Flight Standards office authorizing operation of the aircraft under the Minimum Equipment List."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The letter of authorization authorizing operation under the Minimum Equipment List may be obtained by written request of the airworthiness certificate holder."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "The Minimum Equipment List and the letter of authorization constitute a supplemental type certificate for the aircraft."
    },
    {
      "quote_ref": "F016:F017",
      "scope_refs": ["F013"],
      "kind": "condition",
      "meaning": "For takeoff under paragraph (a), the approved Minimum Equipment List must be prepared in accordance with the limitations specified in paragraph (b) of 14 CFR 91.213."
    },
    {
      "quote_ref": "F016:F018",
      "scope_refs": ["F013"],
      "kind": "condition",
      "meaning": "For takeoff under paragraph (a), the approved Minimum Equipment List must provide for the operation of the aircraft with the instruments and equipment in an inoperable condition."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F013"],
      "kind": "condition",
      "meaning": "For takeoff under paragraph (a), the aircraft records available to the pilot must include an entry describing the inoperable instruments and equipment."
    },
    {
      "quote_ref": "F020",
      "scope_refs": ["F013"],
      "kind": "condition",
      "meaning": "For takeoff under paragraph (a), the aircraft must be operated under all applicable conditions and limitations contained in the Minimum Equipment List and the letter authorizing the use of the list."
    },
    {
      "quote_ref": "F021:F022",
      "scope_refs": ["F021"],
      "kind": "prohibition",
      "meaning": "Instruments and equipment that are either specifically or otherwise required by the airworthiness requirements under which the aircraft is type certificated and which are essential for safe operations under all operating conditions may not be included in a Minimum Equipment List."
    },
    {
      "quote_ref": "F021:F023",
      "scope_refs": ["F021"],
      "kind": "prohibition",
      "meaning": "Instruments and equipment required by an airworthiness directive to be in operable condition may not be included in a Minimum Equipment List unless the airworthiness directive provides otherwise."
    },
    {
      "quote_ref": "F021:F024",
      "scope_refs": ["F021"],
      "kind": "prohibition",
      "meaning": "Instruments and equipment required for specific operations by 14 CFR part 91 may not be included in a Minimum Equipment List."
    },
    {
      "quote_ref": "F025",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "A person authorized to use an approved Minimum Equipment List issued for a specific aircraft under subpart K of 14 CFR part 91, part 121, 125, or 135 must use that Minimum Equipment List to comply with the requirements in 14 CFR 91.213."
    },
    {
      "quote_ref": "F026:F028",
      "scope_refs": ["F026"],
      "kind": "permission",
      "meaning": "Except for operations conducted in accordance with paragraph (a) or (c) of 14 CFR 91.213, a person may take off an aircraft in operations conducted under 14 CFR part 91 with inoperative instruments and equipment without an approved Minimum Equipment List if the flight operation is conducted in a rotorcraft, non-turbine-powered airplane, glider, lighter-than-air aircraft, powered parachute, or weight-shift-control aircraft for which a master minimum equipment list has not been developed, and conditions (2), (3), and (4) of paragraph (d) are satisfied."
    },
    {
      "quote_ref": "F026:F029",
      "scope_refs": ["F026"],
      "kind": "permission",
      "meaning": "Except for operations conducted in accordance with paragraph (a) or (c) of 14 CFR 91.213, a person may take off an aircraft in operations conducted under 14 CFR part 91 with inoperative instruments and equipment without an approved Minimum Equipment List if the flight operation is conducted in a small rotorcraft, nonturbine-powered small airplane, glider, or lighter-than-air aircraft for which a Master Minimum Equipment List has been developed, and conditions (2), (3), and (4) of paragraph (d) are satisfied."
    },
    {
      "quote_ref": "F030:F031",
      "scope_refs": ["F026"],
      "kind": "condition",
      "meaning": "For takeoff without an approved Minimum Equipment List under paragraph (d), the inoperative instruments and equipment must not be part of the VFR-day type certification instruments and equipment prescribed in the applicable airworthiness regulations under which the aircraft was type certificated."
    },
    {
      "quote_ref": "F030:F032",
      "scope_refs": ["F026"],
      "kind": "condition",
      "meaning": "For takeoff without an approved Minimum Equipment List under paragraph (d), the inoperative instruments and equipment must not be indicated as required on the aircraft's equipment list, or on the Kinds of Operations Equipment List for the kind of flight operation being conducted."
    },
    {
      "quote_ref": "F030:F033",
      "scope_refs": ["F026"],
      "kind": "condition",
      "meaning": "For takeoff without an approved Minimum Equipment List under paragraph (d), the inoperative instruments and equipment must not be required by 14 CFR 91.205 or any other rule of 14 CFR part 91 for the specific kind of flight operation being conducted."
    },
    {
      "quote_ref": "F030:F034",
      "scope_refs": ["F026"],
      "kind": "condition",
      "meaning": "For takeoff without an approved Minimum Equipment List under paragraph (d), the inoperative instruments and equipment must not be required to be operational by an airworthiness directive."
    },
    {
      "quote_ref": "F035:F036",
      "scope_refs": ["F026"],
      "kind": "alternative",
      "meaning": "For takeoff without an approved Minimum Equipment List under paragraph (d), as an alternative to deactivation, the inoperative instruments and equipment must be removed from the aircraft, the cockpit control placarded, and the maintenance recorded in accordance with 14 CFR 43.9."
    },
    {
      "quote_ref": "F035:F037",
      "scope_refs": ["F026"],
      "kind": "alternative",
      "meaning": "For takeoff without an approved Minimum Equipment List under paragraph (d), as an alternative to removal, the inoperative instruments and equipment must be deactivated and placarded 'Inoperative'; if deactivation involves maintenance, it must be accomplished and recorded in accordance with 14 CFR part 43."
    },
    {
      "quote_ref": "F038",
      "scope_refs": ["F026"],
      "kind": "condition",
      "meaning": "For takeoff without an approved Minimum Equipment List under paragraph (d), a determination must be made by a pilot who is certificated and appropriately rated under 14 CFR part 61, or by a person who is certificated and appropriately rated to perform maintenance on the aircraft, that the inoperative instrument or equipment does not constitute a hazard to the aircraft."
    },
    {
      "quote_ref": "F039",
      "scope_refs": ["F026"],
      "kind": "statement",
      "meaning": "An aircraft with inoperative instruments or equipment as provided in paragraph (d) of 14 CFR 91.213 is considered to be in a properly altered condition acceptable to the Administrator."
    },
    {
      "quote_ref": "F040",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "Notwithstanding any other provision of 14 CFR 91.213, an aircraft with inoperable instruments or equipment may be operated under a special flight permit issued in accordance with 14 CFR 21.197 and 21.199."
    },
    {
      "quote_ref": "F041",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Historical regulatory citations and amendment metadata for 14 CFR 91.213, containing no substantive operational or compliance requirements."
    }
  ]
}
